mapper.select:
select id, device_id, channel_no, property_id, value_num, value_text,
       value_json::text as value_json, collected_at, created_at
from ipe_ops.device_property_ts
where device_id = #{deviceId}
  and property_id = #{propertyId}
  and collected_at >= #{from}
  and collected_at <= #{to}
order by collected_at
